// Format executive summary and operational highlights
const data = $input.first().json;

const total = data.total_inquiries || 0;
const aiResolved = data.resolved_by_ai || 0;
const escalated = data.escalated_to_staff || 0;
const unresolved = data.unresolved_complaints_count || 0;
const categories = data.top_categories || [];

const catBreakdown = categories.map(c => `• ${c.category}: ${c.count}`).join("\n");

const executiveSummary = `=== GRAND AZURE RESORT: DAILY SUPPORT DIGEST ===\nDate: ${data.report_date}\nTotal Inquiries: ${total}\nAI Automated Resolutions: ${aiResolved}\nStaff Escalations: ${escalated}\nPending Unresolved Complaints: ${unresolved}\n\nTop Categories:\n${catBreakdown}\n\nAI Operations Analysis:\n${data.ai_summary_text}`;

return [{
  json: {
    report_date: data.report_date,
    total_inquiries: total,
    ai_resolved: aiResolved,
    escalated: escalated,
    unresolved: unresolved,
    formatted_report: executiveSummary,
    created_at: new Date().toISOString()
  }
}];

